def P(s,style='p'):return Paragraph(s,ST[style])
def H(s):return P(s,'h1')
def H2(s):return P(s,'h2')
def T(rows,widths=None):
    widths=widths or [1/len(rows[0])]*len(rows[0]); data=[]
    for n,row in enumerate(rows):data.append([P(str(v),'thead' if n==0 else 'tcell') for v in row])
    tb=Table(data,colWidths=[W*q for q in widths],hAlign='LEFT',repeatRows=1)
    tb.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),NAVY),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,PALE]),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.7,CORAL),('GRID',(0,1),(-1,-1),.2,colors.HexColor('#d8dfdd')),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
