def img(path,maxheight=220):
    with PIL.open(path) as x:w,h=x.size
    factor=min(W/w,maxheight/h)
    return Image(str(path),width=w*factor,height=h*factor)

def figs(root,num,key,caption,h=210):
    return [img(root/'figures'/f'{num:02d}_{key}.png',h), P(f'<b>Figure {num}.</b> {caption}', 'cap')]

def Eq(formula,height=36):
    f=plt.figure(figsize=(12,0.8));f.patch.set_alpha(0)
    f.text(.015,.46,'$'+formula+'$',fontsize=18,ha='left',va='center',color='#233b46')
    out=io.BytesIO();f.savefig(out,format='png',dpi=220,bbox_inches='tight',pad_inches=.1,transparent=True);plt.close(f);out.seek(0)
    with PIL.open(out) as b:w,h=b.size
    out.seek(0);factor=min(W/w,height/h)
    return Image(out,width=w*factor,height=h*factor)

def onpage(c,d):
    page=d.page;c.saveState()
    if page>1:
        c.setStrokeColor(CORAL);c.setLineWidth(.9);c.line(46,PH-34,PW-46,PH-34)
        c.setFont('DejaVu-Bold',8.4);c.setFillColor(NAVY);c.drawString(46,PH-26,'paceval.  |  PHARMACOKINETIC RATE KERNEL RESEARCH')
    c.setStrokeColor(colors.HexColor('#dae2df'));c.line(46,36,PW-46,36)
    c.setFont('DejaVu',7.1);c.setFillColor(MUTED);c.drawString(46,23,'paceval | Patient-Specific Pharmacokinetic Rate Kernels | 2026')
    c.drawRightString(PW-46,23,str(page));c.restoreState()

def verified(root):
    ex=(root/'results/sdk_execution.txt').read_text()
    assert 'original paceval SDK execution SUCCESS' in ex
    stats=dict(line.split('=',1) for line in ex.splitlines() if '=' in line)
    assert stats['registered_and_executed_graphs']=='94'
    assert stats['virtual_profiles']=='42' and stats['scenarios']=='168' and stats['time_steps']=='384'
    v=json.loads((root/'results/high_precision_audit.json').read_text())
    assert v['status']=='PASS' and v['total_high_precision_checks']>=9900 and v['graphs_covered']==94
    with (root/'results/scenario_summary.csv').open(newline='') as f:r=list(csv.DictReader(f))
    assert len(r)==168
    hero=root/'figures/00_pharmacokinetic_hero.png'
    with PIL.open(hero) as im:assert im.size==(2400,1200) and im.mode=='RGB'
    return stats,v,r

def build(root):
    s,v,r=verified(root)
    def pick(p,model,route):return next(x for x in r if int(x['virtual_profile_id'])==p and int(x['model_version'])==model and x['route']==route)
    n=lambda d,k:float(d[k]);v1,v2=pick(19,1,'oral'),pick(19,2,'oral')
    med=lambda m,route,k:statistics.median(n(x,k) for x in r if int(x['model_version'])==m and x['route']==route)
    outfile=root/'paceval_Patient_Specific_Pharmacokinetic_Rate_Kernels_Whitepaper_EN.pdf'
    doc=SimpleDocTemplate(str(outfile),pagesize=A4,leftMargin=46,rightMargin=46,topMargin=47,bottomMargin=48,title='Patient-Specific Pharmacokinetic Rate Kernels | paceval',author='paceval. Research',subject='Original-SDK verified research of synthetic pharmacokinetic execution kernels')
    z=[]
    # 1 TITLE
    z += [Spacer(1,11),P('PACEVAL  |  ORIGINAL-SDK VERIFIED SCIENTIFIC RESEARCH','sm'),P('Patient-Specific<br/>Pharmacokinetic Rate Kernels','title'),P('Reusable and version-controlled mathematical execution for synthetic concentration profiles, PK exposure, sensitivity analysis and numerical model assessment','sub'),img(root/'figures/00_pharmacokinetic_hero.png',250),P('<i>Concept illustration; not a computed research result. All subjects and compounds in this report are fictional.</i>','cap'),Spacer(1,10),H2('Research outcome'),P(f"<b>{s['registered_and_executed_graphs']} actual paceval graphs</b> executed on <b>{s['scenarios']} synthetic scenarios</b> (42 virtual profiles, two models and two administration routes); <b>{int(s['multi_graph_batch_calls']):,}</b> real multi-graph batch calls producing <b>{int(s['paceval_graph_outputs']):,}</b> values; <b>{v['total_high_precision_checks']:,}</b> independent 80-digit checks."),P('<b>Scope:</b> closed-form exact transitions of a one-compartment linear model, not a validated drug, patient data, prescribing instrument or clinical treatment recommendation.','p2'),P('Independent numerical research demonstration | 13 November 2026','sm'),PageBreak()]
    # 2 USE CASE
    z += [H('1. Introduction: pharmacokinetic use case and state of the art'),P('Drug-development research frequently asks what concentration–time curve an experimental compound might produce under a defined administration schedule, and how that curve would change if clearance, distribution volume or absorption differed between individuals. Pharmacometric teams use established structural and statistical models to investigate these questions. The usual inputs include compound-specific parameters, administration history, physiological covariates, observed concentrations and an uncertainty model. Common outputs include exposure (AUC), sampled peak or trough concentration, model residuals and parameter sensitivity. None of these outputs alone establishes safe or effective clinical dosing.'),P('Current workflows include nonlinear mixed-effects modelling (NONMEM, Monolix, Pumas, nlmixr2), ODE simulation (e.g. rxode2) and physiologically based tools such as PK-Sim/MoBi. Population models require external evaluation, relevant covariate definitions and scientifically qualified data. In 2024, model-ensembling work illustrated the importance of candidate model selection [4]; a 2024/25 clinical pharmacology review documented established PK software [3]. Open Systems Pharmacology offers a substantially broader PBPK environment [7].'),H2('Current standards and scientific developments'),P('The ICH M15 framework was adopted at Step 4 on 29 January 2026. The FDA issued final guidance in June 2026, and the EMA lists EU effectiveness from 23 July 2026 [1, 2]. This guideline addresses the planning, evaluation and reporting of model-informed drug-development evidence. It does not authorize an unvalidated mathematical kernel as a medical product. FDA guidance on population PK from February 2022 [5] and more recent literature on external model evaluation [6] reinforce the distinction between numerical execution and clinical qualification.'),H2('Research opportunity: reliable reuse of mathematical expressions'),P('The narrowly defined experiment evaluates whether relevant rate, exposure, cost, constraint and sensitivity functions can be assembled into reusable original-paceval computation graphs, then executed for deterministic virtual populations. Compared with a full clinical platform, the project isolates pure mathematical execution; there is no fitting of patient parameters, Bayesian estimation, drug-specific calibration or adaptive-dosing decision logic.'),T([['Illustrative input','Mathematical calculation','Research output'],['Weight, synthetic renal factor, profile perturbations','Two covariate formula versions, CL/V and absorption rates','Independent clearance and half-life versions'],['Fictional administration events','Exact oral-depot / central-compartment transition','Concentration trace, AUC and sampled peak'],['Virtual observation / numerical references','Complete residual, 30 weighted-objective graphs and guard margins','Versioned scores and sensitivities']],[.29,.37,.34]),PageBreak()]
    # 3 SYSTEM
    z += [H('2. Research question and execution architecture'),P('<b>Research question.</b> Can an original paceval Mathematical Engine execute the principal full mathematical chain in a synthetic pharmacokinetic workflow (not merely a trivial rate subterm), preserve two active formula versions, and produce independently verifiable concentration and exposure results?'),P('The C++ host creates the virtual cohort, applies dosing-event state changes, preserves central/depot amounts between intervals, invokes the original batch API, accumulates paceval-derived exposure increments, selects sampled peaks, and writes the output files. paceval owns the scientifically material pure mathematics: clearance, volume, rate constants, exact state transitions, AUC increments, margin expressions, complete objective variants and explicit analytical sensitivities.'),*figs(root,1,'application_workflow','Research architecture. A schematic of the real execution components, not a plot of clinical observations.',172),H2('What the original SDK actually does'),P(f"<b>{s['registered_and_executed_graphs']}</b> distinct formulas are created once using the original <b>paceval_CreateComputation</b>, then evaluated repeatedly using <b>paceval_dGetMultipleComputationsResultsExt</b>. The program first tests a mixed-function/mixed-row buffer ordering with scalar <b>paceval_dGetComputationResult</b> calls. The canonical release records <b>{s['multi_graph_batch_calls']}</b> multi-graph batches and <b>{s['scalar_checks']}</b> scalar control evaluations."),P('Every graph is listed in <b>results/math_execution_inventory.csv</b> with its mathematical expression, units, version, owner and verification path. No mathematical result in the figure set is produced by running a reference model in place of paceval.'),PageBreak()]
    # 4 FORMULAS
    z += [H('3. Mathematical model, dimensions and assumptions'),P('The source WP_046 proposed the one-compartment concentration RHS dC/dt = R/V − CL·C/V. To cover absorption, event-driven dosing and model changes, the experiment adds a first-order depot and derives an exact state transition for piecewise constant parameters. There are two simultaneously retained <i>hypothetical</i> clearance versions for each synthetic subject.'),H2('Covariate parameters; intentionally fictional'),Eq(r'CL_1=CL_0(WT/70)^{0.75}RF\,e^{\eta_{CL}}'),Eq(r'CL_2=CL_0(WT/70)^{0.75}(0.55RF+0.45RF^2)e^{\eta_{CL}}'),Eq(r'V=V_0(WT/70)e^{\eta_V},\qquad k=CL/V'),P('WT is virtual body weight in kg; CL and CL0 are in L/h; V and V0 in L; k in h⁻¹; and RF is a <b>dimensionless experimental parameter</b>, not actual eGFR or a clinical renal-function estimate. The 0.75 allometric exponent is a familiar modelling convention, but the v2 polynomial and all numerical coefficients are unestimated synthetic research choices [3, 8].'),H2('Rate equations and analytical step'),Eq(r'\dot A_g=-k_a A_g,\quad \dot A_c=Fk_aA_g+R-kA_c,\quad C=A_c/V'),Eq(r'A_g^{\prime}=A_g e^{-k_a h}'),Eq(r'A_c^{\prime}=A_c e^{-kh}+\frac{Fk_aA_g}{k_a-k}(e^{-kh}-e^{-k_a h})+\frac{R}{k}(1-e^{-kh})',49),Eq(r'\Delta AUC=\frac{F(A_g-A_g^{\prime})+Rh-(A_c^{\prime}-A_c)}{CL}',42),P('Here Ag and Ac are depot and central amounts (mg), ka is absorption rate (h⁻¹), F is the oral bioavailable fraction, R the active infusion rate (mg/h), h the step interval (h), C in mg/L, and AUC in mg·h/L. The final expression is obtained from the exact elimination mass balance. A new administration can change the depot amount or R only at the step boundary. The tested domain excludes ka near k, where the displayed analytical form requires a stable limiting expression.'),PageBreak()]
    # 5 IMPLEMENTATION
    z += [H('4. Verified mathematical execution coverage'),P('The SDK has 94 executed persistent graphs: 46 functions for each of two versions, plus two cross-version delta graphs. Each version includes the core compartment and covariate formulas, analytical exposure readouts, single-dose controls, explicit sensitivity functions and fifteen independently evaluated objective variants. The synthetically defined observations and reference margins are numerical test variables, not real measured drug concentrations or therapeutic cut-offs.'),T([['Function / domain purpose','Actual owner','Examples of registered graph IDs'],['CL, V, k, half-life; covariate transforms','paceval','clearance_v1/v2; volume_v1/v2; elimination_constant_v1/v2'],['Oral and IV fluxes; full state transitions; concentration','paceval','gut_rate; central_rate; depot_next; central_next; concentration_next'],['Analytical exposure and single-dose PK extrema','paceval','auc_exact_step; auc_infinity_oral; single_oral_tmax; single_oral_cmax'],['Scores and numerical guard margins','paceval','score_v1_01 ... score_v2_15; upper_margin; relative_clearance_margin'],['Sensitivities and model-revision deltas','paceval','cl_sensitivity_rf; concentration_next_sensitivity_rf; clearance_delta_v2_v1'],['Event times, retained state and cross-time reductions','C++ host','Daily event handling, AUC reduction, sampled max selection'],['Scientific oracle and trajectory audit','Independent Python/C++','verify_results.py and native C++ reference functions']],[.30,.17,.53]),H2('Independent reference and traceability'),P(f"The executable performed <b>{s['native_cpp_checks']}</b> independent native C++ checks; the separate 80-decimal-digit mpmath oracle verified <b>{v['high_precision_graph_checks']}</b> selected actual graph-probe outputs and <b>{v['full_trajectory_quantity_checks']}</b> whole-trajectory quantities across <b>{v['full_trajectories']}</b> scenarios. All 94 graph families are covered. The audit passed. Full numeric verification and tolerances are retained in machine-readable technical files, not reproduced as competing-accuracy tables in this scientific report."),P('The state solver uses a closed-form analytical transition, <b>not</b> an adaptive ODE algorithm; adaptive-step behaviour requested in the original proposal is outside the scope of these reported experiments. TINC was not tested, and no general global error or clinical validity guarantee is asserted.'),PageBreak()]
    # 6 WORKLOAD + figure 2
    z += [H('5. Deterministic virtual-population experiment'),P('The fixed workload comprises seven virtual weights (50–110 kg), six dimensionless synthetic renal multipliers, deterministic small covariate heterogeneity terms, two simultaneously available clearance versions and two distinct routes: 240 mg oral into a depot at 24-hour intervals, or 120 mg/h intravenous infusion for the first two hours each day. Four days contain 384 quarter-hour steps and 168 version × route × profile combinations. Bioavailability is below unity for the oral scenarios, so the alternative routes do not represent identical systemic input.'),T([['Research input','Value / interpretation'],['Reference parameters','CL0 = 5 L/h; V0 = 40 L; profile-specific ka and bioavailability'],['Observation / score controls','3 mg/L model target; 6 mg/L illustrative numerical ceiling; AUC reference 40 mg·h/L'],['Time horizon','0–96 h, h = 0.25 h, oral/IV events each 24 h'],['Model revisions','v1: RF; v2: 0.55 RF + 0.45 RF² in clearance'],['Published outputs','Scenario summary, actual concentration traces, graph registry and probe inputs']],[.34,.66]),*figs(root,2,'virtual_profile_concentration','Versioned model trajectories and an intravenous alternative for fictional profile 19. All plotted values come from the executed original paceval graphs.',215),P('The sampled Cmax reduces the 0.25-hour concentration grid, while the AUC sums exact per-step paceval exposure expressions. The two different summary methods must not be confused with continuous-time peak finding or exposure extrapolated beyond 96 hours.','sm'),PageBreak()]
    # 7 fig3 fig4
    z += [H('6. Modelled exposure: renal factor and body weight'),P(f"Across 42 synthetic oral profiles, the median 96-hour AUC is <b>{med(1,'oral','AUC0_h_mg_h_per_L'):.3f} mg·h/L</b> for version 1 and <b>{med(2,'oral','AUC0_h_mg_h_per_L'):.3f} mg·h/L</b> for version 2. These differences arise solely from fictional covariate formulas and synthetic subjects, not clinical evidence."),*figs(root,3,'exposure_by_renal_covariate','For 70-kg virtual subjects, AUC(0–96 h) changes systematically across the dimensionless renal multiplier.',185),*figs(root,4,'exposure_surface_3d','Three-dimensional surface of 42 measured original-paceval output rows (v2, oral); weight and renal factor jointly vary.',238),PageBreak()]
    # 8 figure 5 6
    z += [H('7. Controlled formula revision and peak response'),P('The v2 quadratic covariate family is a retained model revision: both versions are available without replacing or mutating previously registered graph handles. The AUC difference plotted below is formed from actual scenario outputs under the same profile and administration schedule. It is not evidence that one formula is pharmacologically preferable.'),*figs(root,5,'model_revision_exposure_map','AUC(v2) minus AUC(v1) for the 42 fixed oral profiles, in mg·h/L.',202),*figs(root,6,'peak_concentration_by_weight','Cmax sampled at 0.25 h resolution for virtual weight variation under v2. Oral and IV systemic input are not matched.',205),PageBreak()]
    # 9 figure 7 8
    z += [H('8. Distinct subject-level responses and PK summary metrics'),P(f"Under v2, median sampled oral peak concentration across 42 profiles is <b>{med(2,'oral','Cmax_sampled_mg_per_L'):.3f} mg/L</b> versus <b>{med(2,'iv_infusion','Cmax_sampled_mg_per_L'):.3f} mg/L</b> for the illustrative IV regimen. These are numerically defined scenarios of a fictional molecule, not a comparative recommendation for routes of administration."),*figs(root,7,'virtual_subject_variability','Three representative concentration time courses vary because the virtual profiles differ in their deterministic parameters.',209),*figs(root,8,'auc_peak_joint_distribution','AUC and sampled Cmax carry complementary information and are not interchangeable summaries.',190),PageBreak()]
    # 10 figures 9 10
    z += [H('9. Parameter sensitivities and numerical guard functions'),P('The same real graph inventory contains explicit derivatives of clearance with respect to synthetic RF and weight, volume with respect to weight, oral AUC with respect to RF, and one-step concentration and squared-residual objectives with respect to RF. These are hand-derived mathematical expressions verified independently; no undocumented automatic differentiation is claimed.'),*figs(root,9,'versioned_clearance_covariate','Version-preserving clearance formulas for virtual 70-kg subjects. The renal multiplier is dimensionless.',201),*figs(root,10,'illustrative_concentration_margin','Distance to an arbitrary 6 mg/L numerical ceiling, computed by paceval. Negative values indicate a violated illustrative inequality, not a clinical safety assessment.',201),PageBreak()]
    # 11 outcome
    z += [H('10. Interpretation, verification and scientific limitations'),H2('A fully traceable synthetic result'),P(f"For virtual profile 19 under the four-day oral schedule, original paceval results are AUC(0–96 h) <b>{n(v1,'AUC0_h_mg_h_per_L'):.6f}</b> and <b>{n(v2,'AUC0_h_mg_h_per_L'):.6f} mg·h/L</b> in v1 and v2 respectively. The corresponding sampled Cmax values are <b>{n(v1,'Cmax_sampled_mg_per_L'):.6f}</b> and <b>{n(v2,'Cmax_sampled_mg_per_L'):.6f} mg/L</b>. The retained input vector, graph expressions, output files and independent high-precision oracle permit reproduction and audit. This is a mathematical demonstration, not an exposure target."),T([['Outcome for synthetic profile 19, oral','Model v1','Model v2'],['CL (L/h)',f"{n(v1,'CL_L_per_h'):.5f}",f"{n(v2,'CL_L_per_h'):.5f}"],['AUC(0–96 h) (mg·h/L)',f"{n(v1,'AUC0_h_mg_h_per_L'):.5f}",f"{n(v2,'AUC0_h_mg_h_per_L'):.5f}"],['Sampled Cmax (mg/L)',f"{n(v1,'Cmax_sampled_mg_per_L'):.5f}",f"{n(v2,'Cmax_sampled_mg_per_L'):.5f}"],['End-of-day-4 trough (mg/L)',f"{n(v1,'last_daily_trough_mg_per_L'):.5f}",f"{n(v2,'last_daily_trough_mg_per_L'):.5f}"]],[.53,.235,.235]),H2('Verified scope'),P('Actual original SDK graph creation and repeated multi-graph batch evaluation; distinct simultaneous formula versions; full exact state transition, exposure and composite-score graph computations; independent native and 80-digit references; defined units, domain constraints, deterministic event handling and documented scientific chart provenance. The CMake project and CTest chain are supplied.'),H2('Boundary between mathematics and medicine'),P('All subjects and drug parameters are synthetic, with no clinically fitted renal relationship, drug-specific assay, real observation record, measured PK residual distribution, structural model validation, identifiability analysis, external predictive assessment or validated therapeutic window. The case excludes ka approximately equal to k and does not investigate nonlinear elimination, multiple compartments, Bayesian model fitting, population inference, adaptive integration, clinical safety, regulatory clearance or TINC. Finite checks do not prove a universal numerical accuracy property.'),P('Future work could add properly licensed, anonymized observations and independently accepted drug-specific models, with external data qualification and expert review. Such studies should be treated as new research projects, not as an inference already justified by these outputs.'),PageBreak()]
    # 12 reproducibility references
    z += [H('11. Reproducibility and external scientific sources'),P('The ZIP contains the original paceval SDK wrapper files under src/ (upstream copyright and AGPL statements preserved), the CMake executable, deterministic virtual-profile data, machine-readable execution summaries and graph registry, independent mpmath verifier, figure regeneration code and this PDF generator. The externally supplied paceval Linux runtime is excluded and must be provided separately in a manner consistent with its license.'),P('<b>Build:</b> cmake -S src -B build -DCMAKE_BUILD_TYPE=Release -DPACEVAL_RUNTIME=/absolute/path/to/libpaceval_linux_sharedLIB.so','sm'),P('<b>Run:</b> cmake --build build -j ; ctest --test-dir build --output-on-failure ; ./build/pharmacokinetic_kernels --out . --steps 384 --patients 42','sm'),P('<b>Independent checks and graphics:</b> python3 src/verify_results.py --root . ; python3 src/make_figures.py --root . --figures figures ; python3 src/check_readme_math.py ; python3 src/make_whitepaper.py --root .','sm'),T([['Artifact path','Function'],['results/math_execution_inventory.csv; formula_registry.csv','Exact graph formulas, versions, units, ownership and purpose'],['results/graph_probe.csv; sdk_execution.txt','Real batch-input vectors and computed outputs; actual execution log'],['results/scenario_summary.csv; concentration_trajectories.csv','Full scientific application results for all 168 scenarios / selected traces'],['results/high_precision_audit.json; verification_summary.json','Independent 80-decimal-digit whole-result and graph validation status'],['results/figure_manifest.csv; src/make_figures.py','Figure sources, captions, fully regenerated research graphics']],[.50,.50]),H2('Scientific and technology references'),P('[1] ICH, M15 General Principles for Model-Informed Drug Development. Step 4, January 2026; EMA effective July 2026: ema.europa.eu/en/ich-m15-guideline-general-principles-model-informed-drug-development-step-2b-scientific-guideline. [2] FDA, M15 final guidance, June 2026: fda.gov/regulatory-information/search-fda-guidance-documents/m15-general-principles-model-informed-drug-development.','sm'),P('[3] Recommended approaches for integration of population pharmacokinetic modelling with precision dosing in clinical practice, British Journal of Clinical Pharmacology, DOI 10.1111/bcp.16335. [4] Selecting the Best Pharmacokinetic Models for a Priori Model-Informed Precision Dosing with Model Ensembling, 2024, PMC11522197. [5] FDA, Population Pharmacokinetics: Guidance for Industry, February 2022.','sm'),P('[6] Guidance for External Evaluation and Selection of Population Pharmacokinetic Models for Precision Dosing, PubMed 41343019. [7] Open Systems Pharmacology, PK-Sim &amp; MoBi, github.com/Open-Systems-Pharmacology/PK-Sim. [8] Monolix PKPD model library, one-compartment linear absorption/infusion equations. [9] paceval original API and repository: paceval.com/api/ and github.com/paceval/paceval.','sm'),P('<b>Conclusion.</b> Within a clearly delimited synthetic one-compartment workload, this original-SDK study verifies complete reusable pharmacokinetic mathematical graph chains, versioned formula evaluation and independently reproducible PK outputs. It does not establish clinical dosing validity.','p2')]
    doc.build(z,onFirstPage=onpage,onLaterPages=onpage)
